import{H as e,Q as t,bt as n,gt as r,it as i,nt as a,rt as o,tt as s}from"./chunks/framework.sms2Rnvf.js";import"./chunks/assets.CKUgKlCM.js";var c=JSON.parse(`{"title":"Version History","description":"","frontmatter":{},"headers":[],"relativePath":"reporting/version-history.md","filePath":"reporting/version-history.md","lastUpdated":1781102819000}`),l={name:`reporting/version-history.md`};function u(e,c,l,u,d,f){let p=n(`BadgePro`);return r(),s(`div`,null,[c[0]||=t(`div`,{style:{display:`none`},hidden:`true`,"aria-hidden":`true`,"data-nosnippet":``},`Are you an LLM? You can read better optimized documentation at /reporting/version-history.md for this page in Markdown format`,-1),c[1]||=t(`h1`,{id:`version-history`,tabindex:`-1`},[o(`Version History `),t(`a`,{class:`header-anchor`,href:`#version-history`,"aria-label":`Permalink to “Version History”`},`​`)],-1),i(p),c[2]||=a(`<p>The Version History allows you to view previous versions of objects (such as Projects, Findings, Notes, Templates, Designs) and shows you who made changes and when. (Personal notes do not have a version history.)</p><p><img src="/images/finding_history.png" alt="Version History of Finding" width="449" height="411"></p><p>New versions are created time-based and action-based.</p><p>Action-based versions are created when fields change that have a bigger impact on the state of the saved object. For example when:</p><ul><li>an object is created or deleted</li><li>a project is marked as finished</li><li>the project design changes or</li><li>the status or assignee of an object changes</li></ul><p>Time-based versions are created with every save operation. A scheduled task then cleans up the versions so that there is one version for about every two hours. When users pauses for longer, the last state of their changes are saved. If other users make changes in the meantime, it is still possible to view the object at the time where the first user left off.</p><h2 id="deletion" tabindex="-1">Deletion <a class="header-anchor" href="#deletion" aria-label="Permalink to “Deletion”">​</a></h2><p>If you delete a finding or a note in a project, the version history is preserved. You can access deleted items in the project overview.</p><p><img src="/images/deleted_note.png" alt="Access deleted note" width="3024" height="1150"></p><p>However, if you delete a Project, Design or Finding Template, the history is deleted either.</p><h2 id="exports" tabindex="-1">Exports <a class="header-anchor" href="#exports" aria-label="Permalink to “Exports”">​</a></h2><p>If you export an object (e.g. a project) it does not include the version history. This is to prevent unintended leaks of sensitive information and to reduce the file size of exported objects.</p><p>This means that if you export and re-import a project, it will no longer have a version history (but the original project will).</p><h2 id="encrypted-archiving" tabindex="-1">Encrypted Archiving <a class="header-anchor" href="#encrypted-archiving" aria-label="Permalink to “Encrypted Archiving”">​</a></h2><p>If projects are <a href="/insights/archiving">archived</a>, the version history is deleted.</p><h2 id="backups" tabindex="-1">Backups <a class="header-anchor" href="#backups" aria-label="Permalink to “Backups”">​</a></h2><p><a href="/setup/backups">Backups</a> include the version history. If a backup is restored, the version history is either.</p>`,17)])}var d=e(l,[[`render`,u]]);export{c as __pageData,d as default};